import type { MetadataRoute } from "next";
import { color } from "@waylit/ui-tokens";

// Lets the manifest be generated at build time, including for a static export.
export const dynamic = "force-static";

/**
 * Web app manifest, served at /manifest.webmanifest. Colours come from the design tokens.
 * Icons are generated by apps/web/scripts/generate-icons.mjs.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Waylit",
    short_name: "Waylit",
    description: "Open source 3D navigation for electric scooters and bicycles.",
    lang: "en",
    start_url: "/?source=pwa",
    scope: "/",
    display: "standalone",
    orientation: "landscape",
    background_color: color.night950,
    theme_color: color.night950,
    categories: ["navigation", "travel"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/icon-maskable-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
